const bcrypt = require('bcryptjs');
const Client = require('../models/Client');
const Domain = require('../models/Domain');
const Mailbox = require('../models/Mailbox');
const EmailMessage = require('../models/EmailMessage');
const logger = require('./logger');
const domainService = require('../services/domain.service');

const seedDatabase = async () => {
  try {
    // Check if seeding is already done
    const existingClient = await Client.findOne({ email: 'admin@example.com' });
    if (existingClient) {
      logger.info('Database already seeded.');
      return;
    }

    logger.info('Seeding database with initial data...');

    // 1. Create Client (Admin)
    const salt = await bcrypt.genSalt(10);
    const clientPassword = await bcrypt.hash('password123', salt);

    const client = await Client.create({
      email: 'admin@example.com',
      password_hash: clientPassword,
      company_name: 'Example Corp'
    });

    // 2. Create Domain
    const domainName = 'example.com';
    const keys = domainService.generateDkimKeys();
    const domain = await Domain.create({
      client_id: client._id,
      name: domainName,
      verification_token: domainService.generateVerificationToken(),
      is_verified: true,
      mx_status: 'active',
      dkim_private_key: keys.privateKey,
      dkim_public_key: keys.publicKey
    });

    // 3. Create User Mailbox
    const mailboxPassword = await bcrypt.hash('password123', salt);
    const mailbox = await Mailbox.create({
      domain_id: domain._id,
      email: `user@${domainName}`,
      password_hash: mailboxPassword,
      quota_bytes: 1073741824
    });

    // 4. Create Admin Mailbox (So admin can use webmail)
    const adminMailbox = await Mailbox.create({
      domain_id: domain._id,
      email: 'admin@example.com',
      password_hash: clientPassword, // Same as client password
      quota_bytes: 5368709120, // 5GB for admin
      first_name: 'System',
      last_name: 'Admin'
    });

    // 5. Create Email Messages
    await EmailMessage.create([
      {
        mailbox_id: mailbox._id,
        direction: 'inbound',
        from: 'system@smtp-service.com',
        to: mailbox.email,
        subject: 'Welcome to your Inbox',
        text_body: 'This is a seeded email message to get you started.',
        html_body: '<div style="font-family: sans-serif; padding: 20px; background: #f9f9f9; border-radius: 5px;"><h2>Welcome!</h2><p>This is a <strong>seeded</strong> email message to get you started with the platform.</p></div>',
        folder: 'inbox',
        is_read: false,
        created_at: new Date(Date.now() - 3600000) // 1 hour ago
      },
      {
        mailbox_id: mailbox._id,
        direction: 'outbound',
        from: mailbox.email,
        to: 'external@test.com',
        subject: 'Sent Item Test',
        text_body: 'This email appears in your sent items.',
        html_body: '<p>This email appears in your sent items.</p>',
        folder: 'sent',
        is_read: true,
        created_at: new Date()
      },
      {
        mailbox_id: adminMailbox._id,
        direction: 'inbound',
        from: 'setup@eeina.com',
        to: adminMailbox.email,
        subject: 'Admin Dashboard Ready',
        text_body: 'Your administrative and email privileges are active.',
        html_body: '<h3>System Ready</h3><p>You can now manage domains and send emails from the same account.</p>',
        folder: 'inbox',
        is_read: false,
        created_at: new Date()
      }
    ]);

    logger.info('Database seeding completed successfully.');
    logger.info('Credentials -> Client: admin@example.com / password123 | Mailbox: user@example.com / password123');

  } catch (error) {
    logger.error('Seeding Error:', error);
  }
};

module.exports = seedDatabase;

const express = require('express');
const router = express.Router();
const bcrypt = require('bcryptjs');
const jwt = require('jsonwebtoken');
const Client = require('../models/Client');
const Mailbox = require('../models/Mailbox');
const logger = require('../config/logger');

// Unified Login Route
router.post('/', async (req, res) => {
  try {
    const { email, password } = req.body;

    // 1. Try to find as Client (Admin)
    const client = await Client.findOne({ email });
    if (client) {
      const isMatch = await bcrypt.compare(password, client.password_hash);
      if (isMatch) {
        // Find associated mailbox for admin to enable webmail features
        const adminMailbox = await Mailbox.findOne({ email: client.email });

        const tokenPayload = { 
            client_id: client._id,
            email: client.email
        };

        // If admin has a mailbox (created via seed or manually), add ID to token
        // This allows authenticateWebmail middleware to pass
        if (adminMailbox) {
            tokenPayload.mailbox_id = adminMailbox._id;
        }

        const token = jwt.sign(tokenPayload, process.env.JWT_SECRET || 'secret', { expiresIn: '1d' });

        return res.json({
          token,
          role: 'client',
          email: client.email,
          first_name: client.first_name,
          last_name: client.last_name,
          company_name: client.company_name,
          has_mailbox: !!adminMailbox
        });
      }
    }

    // 2. Try to find as Mailbox (Webmail User)
    const mailbox = await Mailbox.findOne({ email });
    if (mailbox) {
      const isMatch = await bcrypt.compare(password, mailbox.password_hash);
      if (isMatch) {
        const token = jwt.sign({ mailbox_id: mailbox._id, email: mailbox.email }, process.env.JWT_SECRET || 'secret', { expiresIn: '1d' });
        return res.json({
          token,
          role: 'mailbox',
          email: mailbox.email,
          first_name: mailbox.first_name,
          last_name: mailbox.last_name
        });
      }
    }

    // 3. Neither found
    return res.status(400).json({ error: 'Invalid email or password' });

  } catch (err) {
    logger.error('Unified Login Error:', err);
    res.status(500).json({ error: 'Login failed' });
  }
});

module.exports = router;

import React, { useState, useEffect } from 'react';
import api from './api';
import LandingView from './views/LandingView';
import AuthView from './views/AuthView';
import ClientDashboard from './views/ClientDashboard';
import WebmailView from './views/WebmailView';
import Spinner from './components/Spinner';
import { User } from './types';
import { ToastProvider } from './components/ToastContext';

export default function App() {
  const [view, setView] = useState<'landing' | 'login' | 'client-dashboard' | 'webmail-dashboard'>('landing');
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  // Check auth on load
  useEffect(() => {
    const initAuth = async () => {
      const token = localStorage.getItem('smtp_token');
      const role = localStorage.getItem('smtp_role');

      if (token && role) {
        try {
          if (role === 'client') {
             const res = await api.get('/api/account/profile');
             setUser({ ...res.data, role: 'client', token });
             // Admin defaults to webmail now to look "like user", can switch to dashboard
             setView('webmail-dashboard'); 
          } else if (role === 'mailbox') {
             const res = await api.get('/api/webmail/profile');
             setUser({ ...res.data, role: 'mailbox', token });
             setView('webmail-dashboard');
          }
        } catch (err) {
          // Token invalid or session expired
          console.error("Session fetch failed", err);
          localStorage.removeItem('smtp_token');
          localStorage.removeItem('smtp_role');
          setView('landing');
        }
      } else {
         setView('landing');
      }
      setLoading(false);
    };

    initAuth();
  }, []);

  const handleLoginSuccess = (userData: User) => {
    setUser(userData);
    localStorage.setItem('smtp_role', userData.role);
    // Admins now land on webmail too
    setView('webmail-dashboard');
  };

  const handleLogout = () => {
    localStorage.removeItem('smtp_token');
    localStorage.removeItem('smtp_role');
    setUser(null);
    setView('landing');
  };

  const handleUserUpdate = (updates: Partial<User>) => {
    if (user) {
        setUser({ ...user, ...updates });
    }
  };

  if (loading) {
    return (
        <div className="min-h-screen bg-gray-50 flex items-center justify-center">
            <div className="flex flex-col items-center">
                <Spinner />
                <p className="mt-4 text-gray-500 text-sm">Loading...</p>
            </div>
        </div>
    );
  }

  return (
    <ToastProvider>
      {view === 'landing' && <LandingView onNavigate={(v) => setView(v as any)} />}

      {view === 'login' && (
        <AuthView onSuccess={handleLoginSuccess} onBack={() => setView('landing')} />
      )}

      {view === 'client-dashboard' && user && (
        <ClientDashboard 
            user={user} 
            onLogout={handleLogout} 
            onUserUpdate={handleUserUpdate}
            onOpenWebmail={() => setView('webmail-dashboard')}
        />
      )}

      {view === 'webmail-dashboard' && user && (
        <WebmailView 
            user={user} 
            onLogout={handleLogout}
            onAdminPanel={user.role === 'client' ? () => setView('client-dashboard') : undefined}
        />
      )}
    </ToastProvider>
  );
}

import React, { useState, useEffect, useCallback } from 'react';
import api from '../api';
import { User, EmailMessage } from '../types';
import { useToast } from '../components/ToastContext';

// Import New Modular Components
import WebmailSidebar from './webmail/WebmailSidebar';
import WebmailMessageList from './webmail/WebmailMessageList';
import WebmailReadingPane from './webmail/WebmailReadingPane';
import WebmailMobileNav from './webmail/WebmailMobileNav';
import WebmailCompose from './webmail/WebmailCompose';
import WebmailSettings from './webmail/WebmailSettings';

interface WebmailViewProps {
    user: User;
    onLogout: () => void;
    onAdminPanel?: () => void;
}

const WebmailView = ({ user, onLogout, onAdminPanel }: WebmailViewProps) => {
  const { addToast } = useToast();

  // Data State
  const [messages, setMessages] = useState<EmailMessage[]>([]);
  const [selectedMsg, setSelectedMsg] = useState<EmailMessage | null>(null);

  // View State
  const [view, setView] = useState<'inbox' | 'sent' | 'drafts'>('inbox');
  const [loadingMessages, setLoadingMessages] = useState(false);

  // Pagination State
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [totalMessages, setTotalMessages] = useState(0);

  // Selection State
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  // Modals State
  const [showCompose, setShowCompose] = useState(false);
  const [showSettings, setShowSettings] = useState(false);

  // Compose Pre-fill State
  const [composeTo, setComposeTo] = useState('');
  const [composeSubject, setComposeSubject] = useState('');
  const [composeBody, setComposeBody] = useState('');
  const [composeDraftId, setComposeDraftId] = useState<string | undefined>();

  // Fetch Messages
  const fetchMessages = useCallback(async (isPolling = false) => {
    if (!isPolling) setLoadingMessages(true);
    try {
      const res = await api.get('/api/webmail/messages', {
        params: { folder: view, page, limit: 20 }
      });
      setMessages(res.data.messages);
      setTotalPages(res.data.pagination.pages);
      setTotalMessages(res.data.pagination.total);
    } catch (err) {
      // If admin has no mailbox created yet, this might 403 or 500.
      console.error(err);
    } finally {
      if (!isPolling) setLoadingMessages(false);
    }
  }, [view, page]);

  useEffect(() => {
    fetchMessages();
    let int: any;
    if (page === 1) {
        int = setInterval(() => fetchMessages(true), 15000);
    }
    return () => clearInterval(int);
  }, [fetchMessages, page]);

  // Reset state on view change
  useEffect(() => {
      setPage(1);
      setSelectedIds(new Set());
      setSelectedMsg(null);
  }, [view]);

  // Handlers
  const handleSelectMessage = async (msg: EmailMessage) => {
    if (msg.folder === 'drafts') {
        setComposeTo(msg.to);
        setComposeSubject(msg.subject);
        setComposeBody(msg.html_body || msg.text_body);
        setComposeDraftId(msg._id);
        setShowCompose(true);
        return;
    }

    setSelectedMsg(msg);
    if (!msg.is_read) {
        setMessages(prev => prev.map(m => m._id === msg._id ? { ...m, is_read: true } : m));
        try { await api.patch(`/api/webmail/messages/${msg._id}/read`); } catch (err) {}
    }
  };

  const toggleSelection = (id: string, e: React.SyntheticEvent) => {
    e.stopPropagation();
    const newSet = new Set(selectedIds);
    if (newSet.has(id)) newSet.delete(id);
    else newSet.add(id);
    setSelectedIds(newSet);
  };

  const toggleSelectAll = () => {
    if (selectedIds.size === messages.length) {
        setSelectedIds(new Set());
    } else {
        setSelectedIds(new Set(messages.map(m => m._id)));
    }
  };

  const handleBatchDelete = async () => {
    if(!confirm(`Delete ${selectedIds.size} messages?`)) return;
    try {
        await api.post('/api/webmail/messages/batch-delete', { ids: Array.from(selectedIds) });
        addToast('Messages deleted', 'success');
        setSelectedIds(new Set());
        fetchMessages();
        if (selectedMsg && selectedIds.has(selectedMsg._id)) {
            setSelectedMsg(null);
        }
    } catch (err) {
        addToast('Failed to delete messages', 'error');
    }
  };

  const handleDelete = async (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if(!confirm('Delete this message?')) return;
    try {
        await api.delete(`/api/webmail/messages/${id}`);
        setMessages(prev => prev.filter(m => m._id !== id));
        if (selectedMsg?._id === id) setSelectedMsg(null);
        addToast('Message deleted', 'success');
    } catch(err) {
        addToast('Failed to delete message', 'error');
        fetchMessages();
    }
  };

  const handleReply = () => {
    if (!selectedMsg) return;
    const replyTo = view === 'inbox' ? selectedMsg.from : selectedMsg.to;
    const replySubject = selectedMsg.subject.startsWith('Re:') ? selectedMsg.subject : `Re: ${selectedMsg.subject}`;

    const dateStr = new Date(selectedMsg.created_at).toLocaleString();
    const cleanFrom = selectedMsg.from.replace(/</g, '&lt;').replace(/>/g, '&gt;');
    const originalContent = selectedMsg.html_body || selectedMsg.text_body.replace(/\n/g, '<br>');

    const quoteHtml = `<p><br></p><p><br></p><blockquote style="margin: 0 0 0 0.8ex; border-left: 1px #ccc solid; padding-left: 1ex;">
    On ${dateStr}, ${cleanFrom} wrote:<br>
    ${originalContent}
    </blockquote>`;

    setComposeTo(replyTo);
    setComposeSubject(replySubject);
    setComposeBody(quoteHtml);
    setComposeDraftId(undefined);
    setShowCompose(true);
  };

  const handleCompose = () => {
      setComposeTo('');
      setComposeSubject('');
      setComposeBody('');
      setComposeDraftId(undefined);
      setShowCompose(true);
  };

  return (
    <div className="flex h-screen bg-gray-50 overflow-hidden font-sans">

      {/* 1. Desktop Sidebar */}
      <WebmailSidebar 
        user={user}
        view={view}
        messages={messages}
        onCompose={handleCompose}
        onViewChange={(v) => { setView(v); setSelectedMsg(null); }}
        onSettings={() => setShowSettings(true)}
        onLogout={onLogout}
        onAdminPanel={onAdminPanel}
      />

      {/* 2. Message List */}
      <WebmailMessageList 
        user={user}
        messages={messages}
        selectedMsg={selectedMsg}
        onSelect={handleSelectMessage}
        view={view}
        loading={loadingMessages}
        onRefresh={() => fetchMessages()}
        selectedIds={selectedIds}
        toggleSelectAll={toggleSelectAll}
        toggleSelection={toggleSelection}
        onBatchDelete={handleBatchDelete}
        page={page}
        totalPages={totalPages}
        setPage={setPage}
        totalMessages={totalMessages}
      />

      {/* 3. Reading Pane */}
      <WebmailReadingPane 
        selectedMsg={selectedMsg}
        onBack={() => setSelectedMsg(null)}
        onDelete={handleDelete}
        onReply={handleReply}
      />

      {/* 4. Mobile Bottom Navigation */}
      {!selectedMsg && (
          <WebmailMobileNav 
            view={view}
            onViewChange={(v) => { setView(v); setSelectedMsg(null); }}
            onCompose={handleCompose}
            onSettings={() => setShowSettings(true)}
            showSettings={showSettings}
          />
      )}

      {/* 5. Compose Modal */}
      <WebmailCompose 
        show={showCompose}
        user={user}
        onClose={() => setShowCompose(false)}
        initialTo={composeTo}
        initialSubject={composeSubject}
        initialBody={composeBody}
        initialDraftId={composeDraftId}
        onSuccess={() => {
            fetchMessages();
        }}
      />

      {/* 6. Settings Modal */}
      {showSettings && (
        <WebmailSettings 
            user={user}
            onClose={() => setShowSettings(false)}
            onLogout={onLogout}
        />
      )}

    </div>
  );
};

