const express = require('express');
const router = express.Router();
const bcrypt = require('bcryptjs');
const jwt = require('jsonwebtoken');
const Mailbox = require('../models/Mailbox');
const Domain = require('../models/Domain');
const EmailMessage = require('../models/EmailMessage');
const { authenticateClient } = require('../middleware/auth');
const logger = require('../config/logger');

// List Mailboxes
router.get('/', authenticateClient, async (req, res) => {
  try {
    // Find all domains owned by client
    const domains = await Domain.find({ client_id: req.user.client_id }).select('_id');
    const domainIds = domains.map(d => d._id);

    const mailboxes = await Mailbox.find({ domain_id: { $in: domainIds } })
      .populate('domain_id', 'name')
      .sort({ created_at: -1 });

    res.json(mailboxes);
  } catch (err) {
    res.status(500).json({ error: 'Failed to fetch mailboxes' });
  }
});

// Impersonate Mailbox (Get Token)
router.post('/:id/impersonate', authenticateClient, async (req, res) => {
  try {
    const mailbox = await Mailbox.findById(req.params.id);
    if (!mailbox) return res.status(404).json({ error: 'Mailbox not found' });

    // Verify ownership via Domain
    const domain = await Domain.findOne({ _id: mailbox.domain_id, client_id: req.user.client_id });
    if (!domain) return res.status(403).json({ error: 'Access denied' });

    const token = jwt.sign({ mailbox_id: mailbox._id, email: mailbox.email }, process.env.JWT_SECRET || 'secret', { expiresIn: '1d' });

    logger.info(`Admin impersonating mailbox: ${mailbox.email}`);

    res.json({ 
        token,
        user: {
            email: mailbox.email, 
            first_name: mailbox.first_name, 
            last_name: mailbox.last_name,
            role: 'mailbox'
        }
    });
  } catch (err) {
    logger.error('Impersonation Error:', err);
    res.status(500).json({ error: 'Failed to generate access token' });
  }
});

// Update Mailbox (Password / Quota / Recovery Email / Names)
router.patch('/:id', authenticateClient, async (req, res) => {
  try {
    const { password, quota_bytes, recovery_email, first_name, last_name } = req.body;

    const mailbox = await Mailbox.findById(req.params.id);
    if (!mailbox) return res.status(404).json({ error: 'Mailbox not found' });

    // Verify ownership via Domain
    const domain = await Domain.findOne({ _id: mailbox.domain_id, client_id: req.user.client_id });
    if (!domain) return res.status(403).json({ error: 'Access denied' });

    if (password) {
        if (password.length < 6) return res.status(400).json({ error: 'Password too short' });
        const salt = await bcrypt.genSalt(10);
        mailbox.password_hash = await bcrypt.hash(password, salt);
    }

    if (quota_bytes !== undefined) mailbox.quota_bytes = quota_bytes;
    if (recovery_email !== undefined) mailbox.recovery_email = recovery_email.trim().toLowerCase();
    if (first_name !== undefined) mailbox.first_name = first_name.trim();
    if (last_name !== undefined) mailbox.last_name = last_name.trim();

    await mailbox.save();

    logger.info(`Mailbox updated: ${mailbox.email}`);
    res.json({ message: 'Mailbox updated successfully', mailbox });
  } catch(err) {
    logger.error('Update Mailbox Error:', err);
    res.status(500).json({ error: 'Failed to update mailbox' });
  }
});

// Delete Mailbox
router.delete('/:id', authenticateClient, async (req, res) => {
  try {
    // 1. Verify ownership via Domain relationship
    const mailbox = await Mailbox.findById(req.params.id);
    if (!mailbox) return res.status(404).json({ error: 'Mailbox not found' });

    const domain = await Domain.findOne({ _id: mailbox.domain_id, client_id: req.user.client_id });
    if (!domain) return res.status(403).json({ error: 'Access denied' });

    // 2. Delete messages
    await EmailMessage.deleteMany({ mailbox_id: mailbox._id });

    // 3. Delete mailbox
    await Mailbox.deleteOne({ _id: mailbox._id });

    logger.info(`Mailbox deleted: ${mailbox.email}`);
    res.json({ message: 'Mailbox deleted successfully' });
  } catch (err) {
    logger.error('Delete Mailbox Error:', err);
    res.status(500).json({ error: 'Failed to delete mailbox' });
  }
});

module.exports = router;

import React, { useState, useEffect } from 'react';
import api from './api';
import LandingView from './views/LandingView';
import AuthView from './views/AuthView';
import ClientDashboard from './views/ClientDashboard';
import WebmailView from './views/WebmailView';
import Spinner from './components/Spinner';
import { User } from './types';
import { ToastProvider } from './components/ToastContext';

export default function App() {
  const [view, setView] = useState<'landing' | 'login' | 'client-dashboard' | 'webmail-dashboard'>('landing');
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  // Check auth on load
  useEffect(() => {
    const initAuth = async () => {
      const token = localStorage.getItem('smtp_token');
      const role = localStorage.getItem('smtp_role');

      if (token && role) {
        try {
          if (role === 'client') {
             const res = await api.get('/api/account/profile');
             setUser({ ...res.data, role: 'client', token });
             // Admin defaults to webmail now to look "like user", can switch to dashboard
             setView('webmail-dashboard'); 
          } else if (role === 'mailbox') {
             const res = await api.get('/api/webmail/profile');
             setUser({ ...res.data, role: 'mailbox', token });
             setView('webmail-dashboard');
          }
        } catch (err) {
          // Token invalid or session expired
          console.error("Session fetch failed", err);
          localStorage.removeItem('smtp_token');
          localStorage.removeItem('smtp_role');
          localStorage.removeItem('smtp_admin_token'); // Clear impersonation token too
          setView('landing');
        }
      } else {
         setView('landing');
      }
      setLoading(false);
    };

    initAuth();
  }, []);

  const handleLoginSuccess = (userData: User) => {
    setUser(userData);
    localStorage.setItem('smtp_role', userData.role);
    // Admins now land on webmail too
    setView('webmail-dashboard');
  };

  const handleLogout = () => {
    localStorage.removeItem('smtp_token');
    localStorage.removeItem('smtp_role');
    localStorage.removeItem('smtp_admin_token');
    setUser(null);
    setView('landing');
  };

  const handleUserUpdate = (updates: Partial<User>) => {
    if (user) {
        setUser({ ...user, ...updates });
    }
  };

  const handleImpersonate = (token: string, impersonatedUser: any) => {
    // 1. Save current admin token
    const currentToken = localStorage.getItem('smtp_token');
    if (currentToken) {
        localStorage.setItem('smtp_admin_token', currentToken);
    }

    // 2. Set new user session
    localStorage.setItem('smtp_token', token);
    localStorage.setItem('smtp_role', 'mailbox');
    setUser(impersonatedUser);
    setView('webmail-dashboard');
  };

  const handleRestoreAdminSession = async () => {
    const adminToken = localStorage.getItem('smtp_admin_token');
    if (adminToken) {
        // Restore Admin Session
        localStorage.setItem('smtp_token', adminToken);
        localStorage.setItem('smtp_role', 'client');
        localStorage.removeItem('smtp_admin_token');

        // Fetch Admin Profile
        try {
            const res = await api.get('/api/account/profile');
            setUser({ ...res.data, role: 'client', token: adminToken });
            setView('client-dashboard');
        } catch (err) {
            // If admin token expired, just logout
            handleLogout();
        }
    }
  };

  const isImpersonating = !!localStorage.getItem('smtp_admin_token');

  if (loading) {
    return (
        <div className="min-h-screen bg-gray-50 flex items-center justify-center">
            <div className="flex flex-col items-center">
                <Spinner />
                <p className="mt-4 text-gray-500 text-sm">Loading...</p>
            </div>
        </div>
    );
  }

  return (
    <ToastProvider>
      {view === 'landing' && <LandingView onNavigate={(v) => setView(v as any)} />}

      {view === 'login' && (
        <AuthView onSuccess={handleLoginSuccess} onBack={() => setView('landing')} />
      )}

      {view === 'client-dashboard' && user && (
        <ClientDashboard 
            user={user} 
            onLogout={handleLogout} 
            onUserUpdate={handleUserUpdate}
            onOpenWebmail={() => setView('webmail-dashboard')}
            onImpersonate={handleImpersonate}
        />
      )}

      {view === 'webmail-dashboard' && user && (
        <WebmailView 
            user={user} 
            onLogout={handleLogout}
            onAdminPanel={user.role === 'client' ? () => setView('client-dashboard') : isImpersonating ? handleRestoreAdminSession : undefined}
        />
      )}
    </ToastProvider>
  );
}

import React, { useState, useEffect } from 'react';
import api from '../api';
import { User, Domain, Mailbox, DnsStatus } from '../types';
import { useToast } from '../components/ToastContext';

// Components
import DashboardNavbar from './dashboard/DashboardNavbar';
import ServerInfoPanel from './dashboard/ServerInfoPanel';
import DomainManager from './dashboard/DomainManager';
import MailboxManager from './dashboard/MailboxManager';

// Modals
import DnsConfigModal from './dashboard/modals/DnsConfigModal';
import SystemLogsModal from './dashboard/modals/SystemLogsModal';
import DiagnosticsModal from './dashboard/modals/DiagnosticsModal';
import AccountSettingsModal from './dashboard/modals/AccountSettingsModal';
import EditMailboxModal from './dashboard/modals/EditMailboxModal';

// Types
interface SystemLog {
  _id: string;
  level: string;
  message: string;
  timestamp: string;
  meta?: any;
}

interface DiagnosticResult {
  dns: { status: 'ok' | 'error'; message: string };
  port25: { status: 'ok' | 'error'; message: string };
  timestamp: string;
}

interface Props {
    user: User;
    onLogout: () => void;
    onUserUpdate: (u: Partial<User>) => void;
    onOpenWebmail: () => void;
    onImpersonate: (token: string, user: any) => void;
}

const ClientDashboard = ({ user, onLogout, onUserUpdate, onOpenWebmail, onImpersonate }: Props) => {
  const { addToast } = useToast();
  const [domains, setDomains] = useState<Domain[]>([]);
  const [mailboxes, setMailboxes] = useState<Mailbox[]>([]);
  const [newDomain, setNewDomain] = useState('');
  const [loading, setLoading] = useState(false);

  // Mailbox creation state
  const [selectedDomainId, setSelectedDomainId] = useState<string | null>(null);
  const [newMailboxEmail, setNewMailboxEmail] = useState('');
  const [newMailboxPassword, setNewMailboxPassword] = useState('');

  // DNS View State
  const [viewDnsDomain, setViewDnsDomain] = useState<Domain | null>(null);
  const [dnsStatus, setDnsStatus] = useState<DnsStatus | null>(null);
  const [checkingDns, setCheckingDns] = useState(false);

  // Logs View State
  const [showLogs, setShowLogs] = useState(false);
  const [logs, setLogs] = useState<SystemLog[]>([]);

  // Diagnostics View State
  const [showDiagnostics, setShowDiagnostics] = useState(false);
  const [diagnosticResult, setDiagnosticResult] = useState<DiagnosticResult | null>(null);
  const [runningDiagnostics, setRunningDiagnostics] = useState(false);

  // Account Settings State
  const [showAccountSettings, setShowAccountSettings] = useState(false);

  // Edit Mailbox State
  const [editingMailbox, setEditingMailbox] = useState<Mailbox | null>(null);

  const refreshData = async () => {
    try {
      const dRes = await api.get('/api/domains');
      setDomains(dRes.data);
      const mRes = await api.get('/api/mailboxes');
      setMailboxes(mRes.data);
    } catch (err) {
      console.error(err);
    }
  };

  useEffect(() => { refreshData(); }, []);

  useEffect(() => {
    let interval: any;
    if (showLogs) {
      fetchLogs();
      interval = setInterval(fetchLogs, 5000);
    }
    return () => clearInterval(interval);
  }, [showLogs]);

  const fetchLogs = async () => {
    try {
      const res = await api.get('/api/system/logs');
      setLogs(res.data);
    } catch (err) {
      console.error(err);
    }
  };

  const runDiagnostics = async () => {
    setShowDiagnostics(true);
    setRunningDiagnostics(true);
    setDiagnosticResult(null);
    try {
      const res = await api.get('/api/system/diagnostics');
      setDiagnosticResult(res.data);
    } catch (err) {
      console.error(err);
      addToast('Failed to run diagnostics', 'error');
    } finally {
      setRunningDiagnostics(false);
    }
  };

  const handleAddDomain = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newDomain) return;
    try {
      await api.post('/api/domains', { name: newDomain });
      setNewDomain('');
      addToast('Domain added successfully', 'success');
      refreshData();
    } catch (err: any) {
      addToast(err.response?.data?.error || 'Failed to add domain', 'error');
    }
  };

  const handleDeleteDomain = async (id: string) => {
    if(!confirm('Are you sure? This will delete all mailboxes and emails associated with this domain.')) return;
    try {
        await api.delete(`/api/domains/${id}`);
        addToast('Domain deleted', 'success');
        refreshData();
    } catch (err: any) {
        addToast(err.response?.data?.error || 'Failed to delete domain', 'error');
    }
  };

  const handleDeleteMailbox = async (id: string) => {
    if(!confirm('Are you sure you want to delete this mailbox? All messages will be lost.')) return;
    try {
        await api.delete(`/api/mailboxes/${id}`);
        addToast('Mailbox deleted', 'success');
        refreshData();
    } catch(err: any) {
        addToast(err.response?.data?.error || 'Failed to delete mailbox', 'error');
    }
  };

  const handleAccessMailbox = async (id: string) => {
      try {
          const res = await api.post(`/api/mailboxes/${id}/impersonate`);
          addToast(`Accessing inbox: ${res.data.user.email}`, 'success');
          onImpersonate(res.data.token, res.data.user);
      } catch (err: any) {
          addToast(err.response?.data?.error || 'Failed to access mailbox', 'error');
      }
  };

  const handleVerify = async (domainId: string) => {
    setLoading(true);
    try {
      await api.post(`/api/domains/${domainId}/verify`);
      await refreshData();
      addToast('Domain Verified Successfully!', 'success');
    } catch (err: any) {
      addToast(err.response?.data?.error || 'Verification Failed', 'error');
    } finally {
      setLoading(false);
    }
  };

  const handleCreateMailbox = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedDomainId) return;

    // Get recovery email from form input directly since we don't have separate state for it
    const formData = new FormData(e.target as HTMLFormElement);
    const recoveryEmail = formData.get('recoveryEmail') as string;

    try {
      await api.post(`/api/domains/${selectedDomainId}/mailboxes`, {
        email: newMailboxEmail,
        password: newMailboxPassword,
        recovery_email: recoveryEmail
      });
      setNewMailboxEmail('');
      setNewMailboxPassword('');
      setSelectedDomainId(null);
      addToast('Mailbox created successfully', 'success');
      refreshData();
    } catch (err: any) {
      addToast(err.response?.data?.error || 'Failed to create mailbox', 'error');
    }
  };

  const openDnsModal = async (domain: Domain) => {
    setViewDnsDomain(domain);
    setDnsStatus(null);
    checkDns(domain);
  };

  const checkDns = async (domain: Domain) => {
    setCheckingDns(true);
    try {
      const res = await api.get(`/api/domains/${domain._id}/dns`);
      setDnsStatus(res.data);
    } catch (error) {
      console.error(error);
    } finally {
      setCheckingDns(false);
    }
  };

  return (
    <div className="min-h-screen bg-gray-100 relative pb-20 font-sans">

      {/* Navigation */}
      <DashboardNavbar 
        user={user} 
        onLogout={onLogout} 
        onShowLogs={() => setShowLogs(true)} 
        onOpenSettings={() => setShowAccountSettings(true)}
        onOpenInbox={onOpenWebmail}
      />

      <main className="max-w-7xl mx-auto py-8 px-4 sm:px-6 lg:px-8">

        {/* Server Health Panel */}
        <ServerInfoPanel 
          onRunDiagnostics={runDiagnostics} 
        />

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

          {/* Domains Section */}
          <div className="lg:col-span-2 space-y-6">
            <DomainManager 
                domains={domains}
                newDomain={newDomain}
                setNewDomain={setNewDomain}
                onAddDomain={handleAddDomain}
                onDeleteDomain={handleDeleteDomain}
                onVerify={handleVerify}
                onOpenDns={openDnsModal}
                loading={loading}
                selectedDomainId={selectedDomainId}
                setSelectedDomainId={setSelectedDomainId}
                newMailboxEmail={newMailboxEmail}
                setNewMailboxEmail={setNewMailboxEmail}
                newMailboxPassword={newMailboxPassword}
                setNewMailboxPassword={setNewMailboxPassword}
                onCreateMailbox={handleCreateMailbox}
            />
          </div>

          {/* Mailboxes Section */}
          <div className="space-y-6">
            <MailboxManager 
                mailboxes={mailboxes} 
                onDeleteMailbox={handleDeleteMailbox}
                onEditMailbox={(mb) => setEditingMailbox(mb)}
                onAccessMailbox={handleAccessMailbox}
            />
          </div>

        </div>
      </main>

      {/* MODALS */}
      {viewDnsDomain && (
        <DnsConfigModal 
            domain={viewDnsDomain}
            status={dnsStatus}
            checking={checkingDns}
            onClose={() => setViewDnsDomain(null)}
            onRefresh={() => checkDns(viewDnsDomain)}
        />
      )}

      {showLogs && (
        <SystemLogsModal 
            logs={logs}
            onClose={() => setShowLogs(false)}
            onRefresh={fetchLogs}
        />
      )}

      {showDiagnostics && (
        <DiagnosticsModal 
            result={diagnosticResult}
            running={runningDiagnostics}
            onClose={() => !runningDiagnostics && setShowDiagnostics(false)}
        />
      )}

      {showAccountSettings && (
        <AccountSettingsModal
            user={user}
            onClose={() => setShowAccountSettings(false)}
            onUpdate={(u) => {
                onUserUpdate(u);
                addToast('Account updated', 'success');
            }}
        />
      )}

      {editingMailbox && (
        <EditMailboxModal 
            mailbox={editingMailbox}
            onClose={() => setEditingMailbox(null)}
            onSuccess={() => { 
                setEditingMailbox(null); 
                refreshData(); 
                addToast('Mailbox updated', 'success');
            }}
        />
      )}

    </div>
  );
};

export default ClientDashboard;

