const WebmailView = ({ user, onLogout, onAdminPanel }: WebmailViewProps) => {
  const { addToast } = useToast();

  // Data State
  const [messages, setMessages] = useState<EmailMessage[]>([]);
  const [selectedMsg, setSelectedMsg] = useState<EmailMessage | null>(null);

  // View State
  const [view, setView] = useState<'inbox' | 'sent' | 'drafts'>('inbox');
  const [loading, setLoading] = useState(false);

  // Pagination State
  const [page, setPage] = useState(1);
  const [pagination, setPagination] = useState({ total: 0, pages: 1 });

  // Selection State
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  // UI State
  const [showCompose, setShowCompose] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  // Compose State
  const [composeData, setComposeData] = useState({ to: '', subject: '', body: '', draftId: undefined as string | undefined });

  // Fetch Messages
  const fetchMessages = useCallback(async (isPolling = false) => {
    if (!isPolling) setLoading(true);
    try {
      const res = await api.get('/api/webmail/messages', {
        params: { folder: view, page, limit: 20 }
      });
      setMessages(res.data.messages);
      setPagination(res.data.pagination);
    } catch (err: any) {
      console.error(err);
      // Auto-logout on 403 Forbidden or 401 Unauthorized (Session Invalid/Expired)
      if (err.response && (err.response.status === 401 || err.response.status === 403)) {
          onLogout();
      }
    } finally {
      if (!isPolling) setLoading(false);
    }
  }, [view, page, onLogout]);

  // Initial Load & Polling
  useEffect(() => {
    fetchMessages();
    let interval: any;
    if (page === 1) {
        interval = setInterval(() => fetchMessages(true), 10000);
    }
    return () => clearInterval(interval);
  }, [fetchMessages, page]);

  // Reset Selection on View Change
  useEffect(() => {
      setPage(1);
      setSelectedIds(new Set());
      setSelectedMsg(null);
      setMobileMenuOpen(false);
  }, [view]);

  // -- Handlers --

  const handleSelectMessage = async (msg: EmailMessage) => {
    if (msg.folder === 'drafts') {
        setComposeData({
            to: msg.to,
            subject: msg.subject,
            body: msg.html_body || msg.text_body,
            draftId: msg._id
        });
        setShowCompose(true);
        return;
    }

    setSelectedMsg(msg);
    // Mark as read locally immediately for UI snap
    if (!msg.is_read) {
        setMessages(prev => prev.map(m => m._id === msg._id ? { ...m, is_read: true } : m));
        try { await api.patch(`/api/webmail/messages/${msg._id}/read`); } catch (err) {}
    }
  };

  const handleCompose = () => {
      setComposeData({ to: '', subject: '', body: '', draftId: undefined });
      setShowCompose(true);
  };

  const handleReply = () => {
    if (!selectedMsg) return;
    const replyTo = view === 'inbox' ? selectedMsg.from : selectedMsg.to;
    const cleanFrom = selectedMsg.from.replace(/</g, '&lt;').replace(/>/g, '&gt;');
    const replyBody = `<p><br></p><blockquote style="border-left: 2px solid #ccc; margin-left: 0; padding-left: 10px; color: #666;">On ${new Date(selectedMsg.created_at).toLocaleString()}, ${cleanFrom} wrote:<br>${selectedMsg.html_body || selectedMsg.text_body}</blockquote>`;

    setComposeData({
        to: replyTo,
        subject: selectedMsg.subject.startsWith('Re:') ? selectedMsg.subject : `Re: ${selectedMsg.subject}`,
        body: replyBody,
        draftId: undefined
    });
    setShowCompose(true);
  };

  const handleDelete = async (id: string) => {
    if(!confirm('Delete this message?')) return;
    try {
        await api.delete(`/api/webmail/messages/${id}`);
        setMessages(prev => prev.filter(m => m._id !== id));
        if (selectedMsg?._id === id) setSelectedMsg(null);
        addToast('Message deleted', 'success');
    } catch(err) {
        addToast('Failed to delete', 'error');
    }
  };

  // Batch Selection Logic
  const toggleSelection = (id: string, e: React.MouseEvent) => {
      e.stopPropagation();
      const next = new Set(selectedIds);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      setSelectedIds(next);
  };

  return (
    <div className="flex h-screen bg-black text-slate-200 overflow-hidden font-sans selection:bg-emerald-500/30 selection:text-emerald-200">

      {/* 1. Sidebar (Navigation) */}
      <WebmailSidebar 
        user={user}
        view={view}
        unreadCount={messages.filter(m => m.folder === 'inbox' && !m.is_read).length}
        onCompose={handleCompose}
        onViewChange={setView}
        onSettings={() => setShowSettings(true)}
        onLogout={onLogout}
        onAdminPanel={onAdminPanel}
        mobileOpen={mobileMenuOpen}
        setMobileOpen={setMobileMenuOpen}
      />

      {/* 2. Message List (The Feed) */}
      <WebmailMessageList 
        messages={messages}
        selectedMsg={selectedMsg}
        selectedIds={selectedIds}
        loading={loading}
        view={view}
        onSelect={handleSelectMessage}
        onToggleSelect={toggleSelection}
        onRefresh={() => fetchMessages()}
        onMobileMenu={() => setMobileMenuOpen(true)}
        pagination={{
            page,
            totalPages: pagination.pages,
            next: () => setPage(p => p + 1),
            prev: () => setPage(p => Math.max(1, p - 1))
        }}
      />

      {/* 3. Reading Pane (The Content) */}
      <WebmailReadingPane 
        message={selectedMsg}
        onClose={() => setSelectedMsg(null)}
        onDelete={() => selectedMsg && handleDelete(selectedMsg._id)}
        onReply={handleReply}
      />

      {/* Modals */}
      <WebmailCompose 
        show={showCompose}
        onClose={() => setShowCompose(false)}
        onSuccess={() => { fetchMessages(); }}
        data={composeData}
        user={user}
      />

      {showSettings && (
          <WebmailSettings user={user} onClose={() => setShowSettings(false)} onLogout={onLogout} />
      )}
    </div>
  );
};

export default WebmailView;

import React, { useState } from 'react';
import { Mailbox } from '../../../types';
import api from '../../../api';
import Spinner from '../../../components/Spinner';

interface Props {
  mailbox: Mailbox;
  onClose: () => void;
  onSuccess: () => void;
}

const EditMailboxModal = ({ mailbox, onClose, onSuccess }: Props) => {
  const [password, setPassword] = useState('');
  const [quota, setQuota] = useState((mailbox as any).quota_bytes ? Math.round((mailbox as any).quota_bytes / 1024 / 1024 / 1024) : 1);
  const [firstName, setFirstName] = useState(mailbox.first_name || '');
  const [lastName, setLastName] = useState(mailbox.last_name || '');

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
        const payload: any = {
            quota_bytes: quota * 1024 * 1024 * 1024,
            first_name: firstName,
            last_name: lastName
        };
        if (password) {
            payload.password = password;
        }

        await api.patch(`/api/mailboxes/${mailbox._id}`, payload);
        onSuccess();
    } catch (err: any) {
        setError(err.response?.data?.error || 'Failed to update mailbox');
    } finally {
        setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 overflow-y-auto" role="dialog" aria-modal="true">
      <div className="flex items-end justify-center min-h-screen pt-4 px-4 pb-20 text-center sm:block sm:p-0">
        <div className="fixed inset-0 bg-gray-600 bg-opacity-75 transition-opacity backdrop-blur-sm" onClick={onClose}></div>
        <span className="hidden sm:inline-block sm:align-middle sm:h-screen">&#8203;</span>

        <div className="inline-block align-bottom bg-white rounded-xl text-left overflow-hidden shadow-xl transform transition-all sm:my-8 sm:align-middle sm:max-w-md w-full">
          <form onSubmit={handleSubmit}>
            <div className="bg-white px-4 pt-5 pb-4 sm:p-6">
                <div className="flex justify-between items-center mb-6">
                    <h3 className="text-lg font-bold text-gray-900">Edit Mailbox</h3>
                    <p className="text-sm text-gray-500">{mailbox.email}</p>
                </div>

                {error && (
                    <div className="mb-4 bg-red-50 text-red-600 text-sm p-3 rounded-lg">
                        {error}
                    </div>
                )}

                <div className="space-y-4">
                    <div className="grid grid-cols-2 gap-3">
                        <div>
                            <label className="block text-xs font-bold text-gray-500 uppercase tracking-wide mb-1">First Name</label>
                            <input 
                                type="text" 
                                className="w-full border-gray-200 bg-gray-50 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none"
                                value={firstName}
                                onChange={e => setFirstName(e.target.value)}
                            />
                        </div>
                        <div>
                            <label className="block text-xs font-bold text-gray-500 uppercase tracking-wide mb-1">Last Name</label>
                            <input 
                                type="text" 
                                className="w-full border-gray-200 bg-gray-50 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none"
                                value={lastName}
                                onChange={e => setLastName(e.target.value)}
                            />
                        </div>
                    </div>

                    <div>
                        <label className="block text-xs font-bold text-gray-500 uppercase tracking-wide mb-1">New Password</label>
                        <input 
                            type="password" 
                            className="w-full border-gray-200 bg-gray-50 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none"
                            placeholder="Leave blank to keep current"
                            value={password}
                            onChange={e => setPassword(e.target.value)}
                            minLength={6}
                        />
                        <p className="text-xs text-gray-400 mt-1">Only enter if you want to change it.</p>
                    </div>

                    <div>
                        <label className="block text-xs font-bold text-gray-500 uppercase tracking-wide mb-1">Storage Quota (GB)</label>
                        <input 
                            type="number" 
                            min="1"
                            max="50"
                            className="w-full border-gray-200 bg-gray-50 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none"
                            value={quota}
                            onChange={e => setQuota(parseInt(e.target.value))}
                        />
                    </div>

                    <div className="mt-6 bg-slate-50 p-4 rounded-lg border border-slate-200">
                        <h4 className="text-xs font-bold text-slate-500 uppercase tracking-wide mb-3">SMTP Configuration (Outbound)</h4>
                        <div className="grid grid-cols-2 gap-4 text-sm">
                            <div>
                                <span className="block text-xs text-slate-400">Server Hostname</span>
                                <div className="font-mono font-medium text-slate-700">{window.location.hostname}</div>
                            </div>
                            <div>
                                <span className="block text-xs text-slate-400">Port</span>
                                <div className="font-mono font-medium text-slate-700">587 <span className="text-xs text-slate-400">(STARTTLS)</span></div>
                            </div>
                            <div>
                                <span className="block text-xs text-slate-400">Username</span>
                                <div className="font-mono font-medium text-slate-700 truncate" title={mailbox.email}>{mailbox.email}</div>
                            </div>
                            <div>
                                <span className="block text-xs text-slate-400">Auth</span>
                                <div className="font-mono font-medium text-slate-700">Normal Password</div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            <div className="bg-gray-50 px-4 py-3 sm:px-6 sm:flex sm:flex-row-reverse">
                <button 
                    type="submit" 
                    disabled={loading}
                    className="w-full inline-flex justify-center rounded-lg border border-transparent shadow-sm px-4 py-2 bg-blue-600 text-base font-medium text-white hover:bg-blue-700 focus:outline-none sm:ml-3 sm:w-auto sm:text-sm"
                >
                    {loading ? <Spinner /> : 'Save Changes'}
                </button>
                <button 
                    type="button" 
                    onClick={onClose} 
                    className="mt-3 w-full inline-flex justify-center rounded-lg border border-gray-300 shadow-sm px-4 py-2 bg-white text-base font-medium text-gray-700 hover:bg-gray-50 focus:outline-none sm:mt-0 sm:ml-3 sm:w-auto sm:text-sm"
                >
                    Cancel
                </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

export default EditMailboxModal;
